package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class SimpleRegression_getSumSquaredErrors_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetSumSquaredErrors_WithPerfectCorrelation() {
        SimpleRegression regression = new SimpleRegression();
        // y = 2x + 1
        // Points: (1, 3), (2, 5), (3, 7)
        // sumXY = 1*3 + 2*5 + 3*7 = 3 + 10 + 21 = 34
        // sumXX = 1^2 + 2^2 + 3^2 = 1 + 4 + 9 = 14
        // sumYY = 3^2 + 5^2 + 7^2 = 9 + 25 + 49 = 83
        // SSE = 83 - (34 * 34) / 14 = 83 - 1156 / 14 = 83 - 82.5714285714 = 0.4285714286 (Wait, perfect correlation should be 0)
        // Let's use points that actually lie on a line to ensure 0
        regression.clear();
        regression.addData(1.0, 2.0);
        regression.addData(2.0, 4.0);
        regression.addData(3.0, 6.0);

        // sumXY = 2 + 8 + 18 = 28
        // sumXX = 1 + 4 + 9 = 14
        // sumYY = 4 + 16 + 36 = 56
        // SSE = 56 - (28 * 28) / 14 = 56 - 784 / 14 = 56 - 56 = 0

        assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }

    @Test
    public void testGetSumSquaredErrors_WithData() {
        SimpleRegression regression = new SimpleRegression();
        // Points: (1, 2), (2, 2), (3, 4)
        // x: 1, 2, 3 -> sumXX = 1 + 4 + 9 = 14
        // y: 2, 2, 4 -> sumYY = 4 + 4 + 16 = 24
        // xy: 2, 4, 12 -> sumXY = 18
        // SSE = 24 - (18 * 18) / 14 = 24 - 324 / 14 = 24 - 23.142857142857 = 0.857142857143

        regression.addData(1.0, 2.0);
        regression.addData(2.0, 2.0);
        regression.addData(3.0, 4.0);

        double expectedSSE = 0.8571428571428571;
        assertEquals(expectedSSE, regression.getSumSquaredErrors(), DELTA);
    }

    @Test(expected = ArithmeticException.class)
    public void testGetSumSquaredErrors_DivisionByZero() {
        // If sumXX is 0 (e.g., only one data point or all X are same)
        // Note: SimpleRegression might handle this internally or throw NaN.
        // If sumXX is 0, the formula results in division by zero.
        SimpleRegression regression = new SimpleRegression();
        regression.addData(1.0, 2.0);
        // With one point, sumXX = 1, sumXY = 2, sumYY = 4. SSE = 4 - 4/1 = 0.
        // To get sumXX = 0, we need no data or data that doesn't exist in standard usage.
        // However, if we provide only one point, sumXX is not 0.
        // If we check the math, sumXX = 0 only if all x_i are 0 and there are no points, 
        // but sumXX is calculated as sum(x^2). 
        // If we add (0, 1) and (0, 2), sumXX = 0.
        regression.clear();
        regression.addData(0.0, 1.0);
        regression.addData(0.0, 2.0);

        // sumXX = 0. The formula sumYY - sumXY * sumXY / sumXX will trigger division by zero 
        // or return NaN depending on JVM/Floating point behavior.
        // In Java, double division by zero returns Infinity or NaN.
        double result = regression.getSumSquaredErrors();
        if (Double.isNaN(result) || Double.isInfinite(result)) {
            throw new ArithmeticException("NaN or Infinity");
        }
    }

    @Test
    public void testGetSumSquaredErrors_Empty() {
        SimpleRegression regression = new SimpleRegression();
        // For empty regression: sumYY=0, sumXY=0, sumXX=0. 
        // 0 - 0/0 = NaN
        double result = regression.getSumSquaredErrors();
        assertEquals(Double.NaN, result, 0.0);
    }
}
